#include <string>
#include <algorithm>

class Solution {
public:
    int minInsertions(std::string s) {
        int insertions = 0;
        int leftOpen = 0;
        int n = s.length();

        for (int i = 0; i < n; ++i) {
            if (s[i] == '(') {
                leftOpen++;
            } else { // s[i] == ')'
                if (i + 1 < n && s[i + 1] == ')') {
                    // Two consecutive ')'
                    i++; 
                } else {
                    // Only one ')' available, we need to add one ')'
                    insertions++;
                }

                if (leftOpen > 0) {
                    leftOpen--;
                } else {
                    // We need a '(' to match this ')' pair
                    insertions++;
                }
            }
        }

        // Each remaining unmatched '(' needs two ')'
        insertions += leftOpen * 2;

        return insertions;
    }
};
